/* depth-i18n.js — shared chrome strings for the depth pages.
 *
 * Loads the depth-strings.json build artifact (generated by
 * packages/langpack — never hand-edited), applies the language to
 * every [data-i18n] element, and sets document direction from the
 * language entry so Arabic flips the layout, not just the glyphs.
 *
 * Fallback is stated: a key missing in the requested language renders
 * English and marks the element data-fell-back, never a blank.
 */

export async function loadStrings() {
  const res = await fetch("js/depth-strings.json");
  return res.json();
}

export function applyChrome(pack, lang) {
  const langs = pack.languages || {};
  const strings = pack.strings || {};
  const entry = langs[lang];
  if (!entry) return { applied: false, reason: `unknown language ${lang}` };

  document.documentElement.lang = lang;
  document.documentElement.dir = entry.direction || "ltr";

  for (const el of document.querySelectorAll("[data-i18n]")) {
    const key = el.getAttribute("data-i18n");
    const local = (strings[lang] || {})[key];
    if (local) {
      el.textContent = local;
      el.removeAttribute("data-fell-back");
    } else {
      const base = (strings[pack.fallback] || {})[key];
      if (base) {
        el.textContent = base;
        el.setAttribute("data-fell-back", pack.fallback);
      }
      /* no fallback either: leave the existing text — stated, not blank */
    }
  }
  return { applied: true, direction: entry.direction };
}

/* Populate a language <select> from the pack — entries carry their
 * endonym and direction; the caller keeps its own default. */
export function fillLanguageSelect(sel, pack, current) {
  sel.innerHTML = "";
  for (const [code, entry] of Object.entries(pack.languages || {})) {
    const opt = document.createElement("option");
    opt.value = code;
    opt.textContent = entry.name + (entry.direction === "rtl" ? " (RTL)" : "");
    if (code === current) opt.selected = true;
    sel.appendChild(opt);
  }
}
